var $bm_rt;
var rateOfSpeed, clockStartTime, clockTimeNumber, minutes, seconds;
rateOfSpeed = 1;
clockStartTime = thisComp.layer('Control').effect('Slider Control')('Slider');
clockTimeNumber = Math.floor($bm_sub(clockStartTime, $bm_mul(rateOfSpeed, time)));
function addZero(n) {
    if (n < 10)
        return $bm_sum('0', n);
    else
        return n;
}
minutes = Math.floor($bm_div(clockTimeNumber, 60));
seconds = $bm_mod(clockTimeNumber, 60);
$bm_rt = $bm_sum($bm_sum(minutes, ':'), addZero(seconds));
